// State

const state = {
  fileName: null,
  data: null,
  leagueIdx: 0,
  snaps: new Map(),        // `${leagueIdx}:${pid}` -> original attributes/skills
  profiles: [],            // per league skill profiles (from original data)
  leagueAvg: [],           // per league average attribute vector
  userTeams: new Set(),    // team ids the user controls (current league)
  auto: {},                // leagueIdx -> bump summary
  rookieAuto: {},          // leagueIdx -> rookie bump summary
  summer: {},              // leagueIdx -> { players, points } once the age adjustment ran this session
  summerTour: {},          // leagueIdx -> { result, stage, reward } once the summer league tournament started
  rookieNums: {},          // leagueIdx -> { locked, picks: { pid: from } } for rookie jersey numbers
  numPick: null,           // rookie whose number wall is open
  mentor: {},              // leagueIdx -> { seed, list: [{ teamId, mentorId, menteeId, skill, cpu }] }
  contracts: {},           // leagueIdx -> rookie contract changes (for undo)
  fa: {},                  // leagueIdx -> free agency day state
  awards: {},              // leagueIdx -> Map pid -> points awarded
  draft: {},               // leagueIdx -> { lottery, mock, trades }
  compPools: {},
  compCache: {},
  params: loadParams(),
  dirty: false,
  stack: [],
};

function loadParams() {
  try {
    const saved = JSON.parse(localStorage.getItem('hlc:params'));
    if (saved) {
      // v3 changed the bump to award points; older settings don't apply.
      if ((saved.version || 0) < 3) return structuredClone(DEFAULT_PARAMS);
      // v4 flipped summer league recovery (older rookies win back more).
      if (saved.version < 4 || saved.version < 12) delete saved.recoveryBands; // v12: rookies are all 21 or younger
      // v5 rescaled injury risk for natural (unedited) injuries.
      if (saved.version < 5) for (const k of ['injuryMinGames', 'injuryPotPerGame']) delete saved[k];
      if (saved.version < 7) for (const k of ['softTissueParts', 'softTissueMult', 'softTissuePointsMult', 'structuralParts', 'structuralMult']) delete saved[k]; // v7 injury classes
      if (saved.version < 8) delete saved.structuralParts; // v8 added Ankle, Back
      if (saved.version < 9) for (const k of ['mentorMinAge', 'menteeMaxAge', 'mentorPosRange']) delete saved[k]; // v9 mentorship rules
      if (saved.version < 10) for (const k of ['regDownProdZ', 'regDownProdChance']) delete saved[k]; // v10 trainer tuning
      if (saved.version < 11) for (const k of ['potUpChance', 'prodPotUpPerZ', 'prodPotDownZ', 'prodPotDownChance', 'potDownChance', 'rookieR1Mult', 'rookieR2Mult', 'rookieUndraftedMult']) delete saved[k]; // v11 potential balance
      return { ...structuredClone(DEFAULT_PARAMS), ...saved };
    }
  } catch { /* storage unavailable */ }
  return structuredClone(DEFAULT_PARAMS);
}
// Hoop Land's rookies are all 21 or younger, so age alone gives them little
// back: a 21-year-old gets +2; a prospect graded #1 Pick or Top 5 gets +1;
// never more than +2 in all. The grade is the one scouts gave before the
// draft, remembered per season.
const gradeMemoKey = () => `hlc:grades:${seasonKey()}`;
function gradeMemo() {
  const c = (state.gradeMemo ||= {});
  const k = gradeMemoKey();
  if (!c[k]) { try { c[k] = JSON.parse(localStorage.getItem(k)) || {}; } catch { c[k] = {}; } }
  return c[k];
}
function rememberGrades(L) {
  const m = gradeMemo();
  for (const p of L.draftClass || []) m[p.id] = gradeOf(p)[0];
  try { localStorage.setItem(gradeMemoKey(), JSON.stringify(m)); } catch { /* ignore */ }
}
// Grading needs the class's floors, and a floor needs the bonus: while the
// board vectors are being built, grade by the plain floor instead of looping.
let vecsBuilding = false;
setRecoveryBonus(p => {
  let g = gradeMemo()[p.id];
  if (!g && !vecsBuilding) { try { if (league().season.phase === PHASE_PRE_DRAFT) g = gradeOf(p)[0]; } catch { /* no class to grade against */ } }
  return g === '#1 Pick' || g === 'Top 5' ? 1 : 0;
});
// Readiness: how much of the game's −4 draft drop a rookie wins back right away, by his motor, whatever his age.
// Relentless workers (motor 15+) are Pro-Ready (−2 net), most are Base (−3), low-motor players (10 or less) are Projects (−4).
const READINESS = { pro: { tag: 'Pro-Ready', icon: '🎯', back: 2, cls: 'up' }, base: { tag: 'Base', icon: '⚖️', back: 1, cls: 'muted' }, project: { tag: 'Project', icon: '🛠️', back: 0, cls: 'gold' } };
function readinessOf(p) {
  const m = traitsSet(p) ? tr(p, 'motor') : 10;
  return m >= 15 ? READINESS.pro : m <= 10 ? READINESS.project : READINESS.base;
}
const readyChip = p => { const r = readinessOf(p); return `<span class="badge ${r.cls === 'up' ? 'lvl' : r.cls === 'gold' ? 'new' : ''}" title="Draft drop ${r.back - 4}">${r.icon} ${r.tag}</span>`; };
setReadiness(p => (state.params.readiness === 'age' ? null : readinessOf(p).back));
function saveParams() {
  try { localStorage.setItem('hlc:params', JSON.stringify({ ...state.params, version: 12 })); } catch { /* ignore */ }
}
function teamsKey() { return `hlc:teams:${saveTag()}:${state.leagueIdx}`; }
function saveUserTeams() {
  try { localStorage.setItem(teamsKey(), JSON.stringify([...state.userTeams])); } catch { /* ignore */ }
}
function loadUserTeams() {
  let ids = null;
  // Franchise saves: always the team the save is built around.
  { const L = league(); if (L.season.mode === 0 && L.teams.some(t => t.id === L.season.teamId)) { state.userTeams = new Set([L.season.teamId]); state.autoTeams = new Set(); return; } }
  state.autoTeams = new Set();
  if (CAR.isCareer(league())) { state.userTeams = new Set(); return; }   // career: you're a player, every team is the CPU's
  loadAutoTeams();
  try { ids = JSON.parse(localStorage.getItem(teamsKey())); } catch { /* ignore */ }
  if (!Array.isArray(ids)) {
    const L = league();
    ids = L.teams.filter(t => t.isPlayer).map(t => t.id);
    // Franchise saves: default to the team the save is built around.
    if (!ids.length && L.season.mode === 0 && L.teams.some(t => t.id === L.season.teamId)) ids = [L.season.teamId];
  }
  state.userTeams = new Set(ids);
}

const league = () => state.data.seasonLeagues[state.leagueIdx];

// Pre-draft ratings and the summer-league-done flag are remembered per
// league + season so they survive switching save files.
// Which save a stored thing belongs to. Every save made from the same league carries the same save name (the league
// template's), so your team is part of it: two franchises in one league never share offseason state.
// A career save follows its player instead (his team changes when he moves).
const saveTag = (L = league()) => `${L.meta?.saveName || ''}#${L.season.mode === 2 && L.season.playerId > 0 ? `p${L.season.playerId}` : L.season.teamId ?? ''}`;
const seasonKey = (L = league()) => `${L.shortName}:${saveTag(L)}:${L.season.currentYear}`;
function loadOriginals(L = league()) {
  try { return JSON.parse(localStorage.getItem(`hlc:orig:${seasonKey(L)}`)) || {}; } catch { return {}; }
}
function saveOriginals(L, map) {
  const merged = { ...loadOriginals(L), ...map };
  try { localStorage.setItem(`hlc:orig:${seasonKey(L)}`, JSON.stringify(merged)); } catch { /* ignore */ }
  return merged;
}
function summerDone(L = league()) {
  try { return localStorage.getItem(`hlc:summer:${seasonKey(L)}`) === '1'; } catch { return false; }
}
function markSummerDone(L) {
  try { localStorage.setItem(`hlc:summer:${seasonKey(L)}`, '1'); } catch { /* ignore */ }
}
const snapKey = (pid, li = state.leagueIdx) => `${li}:${pid}`;
// Baseline ratings for a player: taken at load, or the first time a player
// shows up later (prospects joining rosters or free agency in-app).
const snapOf = p => {
  const k = snapKey(p.id);
  if (!state.snaps.has(k)) state.snaps.set(k, snapshot(p));
  return state.snaps.get(k);
};
// Commissioner autopilot: a team you run can be handed to the CPU (it stays on your My Teams list).
const isUserTeam = t => t && state.userTeams.has(t.id) && !state.autoTeams?.has(t.id);
const autoKey = () => `hlc:autopilot:${saveTag()}`;
// Career mode: the team the career player is on this season is "your team" on every screen, to look at only. Its
// moves stay the CPU's, like any other team's (isUserTeam is false for it).
const careerTeamNow = () => { const L = league(); return CAR.isCareer(L) ? CAR.careerPlayer(L)?.team || null : null; };
const viewTeams = () => { const t = careerTeamNow(); return t ? [t] : league().teams.filter(isUserTeam); };
const viewOnlyNote = () => `<p class="note small muted">👀 Career mode: the ${esc(careerTeamNow()?.shortName || '')} front office makes these calls, like every other team's. You can look and simulate.</p>`;
function loadAutoTeams() { try { state.autoTeams = new Set(JSON.parse(localStorage.getItem(autoKey())) || []); } catch { state.autoTeams = new Set(); } }
function saveAutoTeams() { try { localStorage.setItem(autoKey(), JSON.stringify([...state.autoTeams])); } catch { /* ignore */ } }

function allEntries() { return leaguePlayers(league(), true); }
function findPlayer(pid) {
  const e = allEntries().find(e => e.p.id === pid);
  if (e) return e;
  const h = (league().hallOfFame || []).find(p => p.id === pid);
  return h ? { p: h, team: null, hof: true } : null;
}

// ---------------------------------------------------------------------------
// Utilities

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Stars drawn as icons. The row is as long as the player's potential
// (`halfStars`, in half stars; a half star is the left half of a star) and
// always starts where a 5-star row starts, so shorter rows leave the gap on
// the right. Gold fills to his current level (`now`, in stars); red outline
// = what age has taken (`now` up to `peak`); the faint outline beyond is
// room still to grow.
const STAR_PATH = 'M12 2.4l2.95 6.1 6.65.85-4.9 4.55 1.3 6.6L12 17.2l-5.95 3.3 1.3-6.6-4.9-4.55 6.65-.85z';
// The left half of the same star, closed along the middle.
const HALF_PATH = 'M12 2.4V17.2l-5.95 3.3 1.3-6.6-4.9-4.55 6.65-.85z';
function stars(halfStars, now = halfStars / 2, peak = now) {
  const total = halfStars / 2;
  const gold = Math.max(0, Math.min(total, now));
  const red = Math.max(gold, Math.min(total, peak));
  const clip = (a, b) => `clip-path:inset(0 ${(100 - b * 100).toFixed(1)}% 0 ${(a * 100).toFixed(1)}%)`;
  const svg = (cls, a, b, half) => (b > a ? `<svg viewBox="0 0 24 24" class="${cls}" style="${half && b >= 0.5 && a <= 0 ? '' : clip(a, b)}"><path d="${half ? HALF_PATH : STAR_PATH}"/></svg>` : '');
  const out = [];
  for (let i = 0; i < Math.ceil(total); i++) {
    const end = Math.min(1, total - i);
    const g = Math.max(0, Math.min(end, gold - i));
    const r = Math.max(g, Math.min(end, red - i));
    const half = end < 1;
    out.push(`<span class="st"${half ? ' style="width:8.5px"' : ''}>${svg('st-faint', r, end, half)}${svg('st-gold', 0, g, half)}${svg('st-lost', g, r, half)}</span>`);
  }
  const lbl = `${total} star potential, ${Math.round(gold * 10) / 10} now${red > gold ? `, ${Math.round((red - gold) * 10) / 10} lost to age` : ''}`;
  return `<span class="st-row" aria-label="${lbl}">${out.join('')}</span>`;
}

function logoUrl(url) {
  if (!url) return '';
  return url.includes('dropbox.com') ? url.replace(/([?&])dl=0/, '$1raw=1') : url;
}
// Logos load right away (no lazy loading) into a box of fixed size, so a
// slow or missing logo never shifts the layout.
function logoImg(team, cls = 'logo-sm') {
  const u = logoUrl(team.logoURL);
  if (!u) return `<span class="${cls} logo-ph" aria-hidden="true"></span>`;
  // A logo that fails to load tries again a couple of times before it's given up on.
  return `<img class="${cls}" src="${esc(u)}" alt="" width="34" height="34" decoding="async" referrerpolicy="no-referrer" onerror="var t=(+this.dataset.t||0)+1;this.dataset.t=t;if(t<=2){var s=this.src.split('#')[0],e=this;setTimeout(function(){e.src=s+(s.indexOf('?')<0?'?':'&')+'r='+t},600*t)}else{this.style.visibility='hidden'}">`;
}
// Fetch every team logo as soon as a save loads (and keep them), so screens
// open with their logos already there. Failed loads retry; logosPending() /
// whenLogosReady() let the draft wait until they're all in.
const logoCache = new Map();
function loadLogo(u, entry, tries = 0) {
  const img = new Image();
  img.referrerPolicy = 'no-referrer';
  img.decoding = 'async';
  try { img.fetchPriority = 'high'; } catch { /* older browsers */ }
  img.onload = () => { entry.done = true; entry.img = img; };
  img.onerror = () => { if (tries < 3) setTimeout(() => loadLogo(u, entry, tries + 1), 500 * (tries + 1)); else entry.done = true; };
  img.src = tries ? `${u}${u.includes('?') ? '&' : '?'}r=${tries}` : u;
  entry.img = img;
}
function preloadLogos(data) {
  const urls = new Set();
  for (const L of data.seasonLeagues || []) for (const t of L.teams || []) { const u = logoUrl(t.logoURL); if (u) urls.add(u); }
  for (const u of urls) {
    if (logoCache.has(u)) continue;
    const entry = { done: false, img: null };
    logoCache.set(u, entry);
    loadLogo(u, entry);
  }
}
const logosPending = () => [...logoCache.values()].some(x => !x.done);
const whenLogosReady = (ms = 5000) => new Promise(res => {
  const t0 = Date.now();
  const tick = () => (!logosPending() || Date.now() - t0 > ms ? res() : setTimeout(tick, 100));
  tick();
});

// A notification that slides down from the top, like a text message.
// `detail` adds a second line (trade alerts show the deal).
// College runs without the pop-ups; only warnings (a tap that did nothing,
// and why) still show there.
function toast(msg, detail = '', ms = detail ? 4000 : 2400, warning = false) {
  if (!warning && state.data && isCollege()) return;
  document.querySelector('.toast')?.remove();
  const t = document.createElement('div');
  t.className = 'toast';
  t.setAttribute('role', 'status');
  t.innerHTML = `<img src="icons/alert.png" alt=""><span><b>${esc(msg)}</b>${detail ? `<span>${esc(detail)}</span>` : ''}</span>`;
  t.addEventListener('click', () => t.classList.add('out'));
  document.body.appendChild(t);
  requestAnimationFrame(() => t.classList.add('in'));
  setTimeout(() => t.classList.add('out'), ms);
  setTimeout(() => t.remove(), ms + 400);
}

function overlay(html) {
  const o = document.createElement('div');
  o.className = 'overlay';
  o.innerHTML = `<div class="box">${html}</div>`;
  document.body.appendChild(o);
  return o;
}

// A question with several answers: choices = [[value, label, class]].
function choiceBox(msg, choices) {
  return new Promise(resolve => {
    const o = overlay(`<p class="note">${msg}</p>
      <div class="stack">${choices.map(([v, l, c]) => `<button class="btn ${c || ''}" data-r="${esc(v)}">${esc(l)}</button>`).join('')}</div>`);
    o.addEventListener('click', e => {
      const b = e.target.closest('[data-r]');
      if (!b) return;
      o.remove();
      resolve(b.dataset.r);
    });
  });
}

function confirmBox(msg, okLabel = 'Confirm', cancelLabel = 'Cancel') {
  return new Promise(resolve => {
    const o = overlay(`<p class="note">${msg}</p>
      <div class="grid2"><button class="btn off" data-r="0">${esc(cancelLabel)}</button><button class="btn focus" data-r="1">${esc(okLabel)}</button></div>`);
    o.addEventListener('click', e => {
      const b = e.target.closest('[data-r]');
      if (!b) return;
      o.remove();
      resolve(b.dataset.r === '1');
    });
  });
}

const nextFrame = () => new Promise(r => requestAnimationFrame(() => setTimeout(r, 30)));

function changeSummary(d) {
  const parts = Object.entries(d.attrs).map(([k, v]) => `${k}${v > 0 ? '+' : ''}${v}`);
  return parts.join(' ');
}

function skillBadges(d) {
  return d.added.map(id => `<span class="badge new">+${esc(skillName(id))}</span>`).join('') +
    d.leveled.map(id => `<span class="badge lvl">${esc(skillName(id))}↑</span>`).join('') +
    d.removed.map(id => `<span class="badge">−${esc(skillName(id))}</span>`).join('');
}

// "Shooting · elite · TPT · MID"
function skillTag(id) {
  const elite = isEliteSkill(id) ? `elite: ${ELITE_REQUIREMENTS[id] ? `${ELITE_REQUIREMENTS[id]} ${ELITE_MIN}+` : `${ELITE_MIN}/20`}` : '';
  return [skillCategory(id), isFreeSkill(id) ? 'free' : elite, skillHint(id)].filter(Boolean).join(' · ');
}

function skillHint(id) {
  const prof = state.profiles[state.leagueIdx]?.[id];
  const avg = state.leagueAvg[state.leagueIdx];
  if (!prof || !avg) return '';
  return ATTRS.map((k, i) => [k, prof.v[i] - avg[i]])
    .sort((a, b) => b[1] - a[1]).slice(0, 2).map(x => x[0]).join(' · ');
}

// ---------------------------------------------------------------------------
// Layout + routing

function layout({ title, left = '', right = '', body, action = null, actionLeft = null, bare = false }) {
  const t = esc(title);
  $app.innerHTML = `
    ${bare ? `<h1 class="sr-only">${t}</h1>` : `<div class="header">
      ${state.stack.length > 1 ? `<button class="btn back" data-act="back" aria-label="Back">${BACK_ARROW}</button>` : ''}
      ${left}
      <div class="marquee" role="heading" aria-level="1" aria-label="${t}">
        <div class="marquee-track" aria-hidden="true"><span>${t}</span><span>${t}</span></div>
      </div>
      ${right || careerChips()}
    </div>`}
    <main class="panel ${bare ? 'bare' : ''}">${body}</main>
    ${action ? `<div class="bottom ${actionLeft ? 'two' : ''}">${actionLeft ? `<button class="btn action alt" data-act="${actionLeft.act}" data-id="${actionLeft.id}">${esc(actionLeft.label)}</button>` : ''}<button class="btn action" data-act="${action.act}"${action.k ? ` data-k="${esc(action.k)}"` : ''}${action.n != null ? ` data-n="${action.n}"` : ''}${action.to ? ` data-to="${esc(action.to)}"` : ''}>${esc(action.label)}</button></div>` : ''}`;
}

const BACK_ARROW = `<svg width="40" height="28" viewBox="0 0 10 7" shape-rendering="crispEdges" aria-hidden="true">
  <path fill="#fff" d="M3 0h1v1h-1zM2 1h2v1h-2zM1 2h9v3h-9zM0 3h1v1h-1zM2 5h2v1h-2zM3 6h1v1h-1z"/></svg>`;

const screens = {};
const actions = {};

function go(name, args = {}) {
  if (!screenAllowed(name)) { toast('Finish the current step on the calendar first', '', 2400, true); return; }
  state.stack[state.stack.length - 1].y = window.scrollY;
  state.stack.push({ name, args });
  history.pushState({ depth: state.stack.length }, '');
  render();
}
// The league's logo: the pro mark for pro leagues, a ball for college.
function leagueBadge(L) {
  return `<img class="league-logo" src="icons/${L.leagueType === 0 ? 'pro-logo.png' : 'league-ball.png'}" alt="">`;
}

function goHome() {
  const n = state.stack.length - 1;
  state.stack = [{ name: 'main', args: {} }];
  if (n > 0) history.go(-n); else render();
  render();
}
function back() {
  if (state.stack.length > 1) history.back();
}
function replace(name, args = {}) {
  state.stack[state.stack.length - 1] = { name, args };
  render();
}
// Re-rendering the same screen (a tap that updates it) keeps your place;
// a new screen, tab or view starts at the top.
let lastView = '';
function render() {
  if (state.data) { FA.setQualifyingOffers(optStore().qo); FA.setCapSystem(isComplete() && state.params.capSystem !== false && !isCollege()); FA.setComplete(isComplete() && !isCollege(), FA.capLines(league()).cap); FX.setFacilitiesOn(isComplete() && !isCollege()); if (!isCollege()) syncGrudges(); if (!isCollege()) syncDead(); }
  if (state.data && isCollege() && state.cal) { try { localStorage.setItem(collegeCalKey(), JSON.stringify(state.cal)); } catch { /* ignore */ } }
  if (state.data && !isCollege()) { seasonDrift(); cpuComebacks(); cpuNumbers(); cpuJerseys(); }   // once an offseason each
  if (state.data && !isCollege()) { careerSync(); syncScarcity(); poSettle(); }
  const top = state.stack[state.stack.length - 1];
  const view = `${state.stack.length}:${top.name}:${top.args?.tab ?? ''}:${top.name === 'fa' ? '' : top.args?.view ?? ''}:${top.args?.id ?? ''}`;
  const y = window.scrollY;
  $app.dataset.screen = top.name;
  screens[top.name](top.args);
  let target = view === lastView ? y : top.y ?? 0;
  if (view === lastView && state.anchor) {
    const n = document.querySelector(`[data-anchor="${state.anchor.key}"]`);
    if (n) target = Math.max(0, n.getBoundingClientRect().top + window.scrollY - state.anchor.top);
  }
  state.anchor = null;
  if (state.toTop) { target = 0; state.toTop = false; }   // an action that wants its results at the top of the page
  window.scrollTo(0, target);
  // iOS can drop a scroll made while it's still finishing a tap; put it
  // back once the redraw has settled.
  const keep = () => { if (Math.abs(window.scrollY - target) > 2) window.scrollTo(0, target); };
  requestAnimationFrame(keep);
  setTimeout(keep, 80);
  top.y = null;
  lastView = view;
}

// The app keeps its own scroll positions per screen.
if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
window.addEventListener('popstate', () => {
  if (state.stack.length < 2) return;
  state.stack.pop();
  render();
});

window.addEventListener('beforeunload', e => {
  if (state.dirty) { e.preventDefault(); e.returnValue = ''; }
});

// A dropdown marked data-keep remembers whether it's open, so a redraw (a tap inside it) never folds it up.
$app.addEventListener('toggle', e => { const k = e.target?.dataset?.keep; if (k) (state.keepOpen ||= {})[k] = e.target.open; }, true);
function runAct(el, e) {
  const act = el.dataset.act;
  if (act === 'back') return back();
  const fn = actions[act];
  state.curAct = act; state.curWhy = null;
  // Keep the card you tapped where it is on screen through the redraw.
  const box = el.closest('[data-anchor]');
  state.anchor = box ? { key: box.dataset.anchor, top: box.getBoundingClientRect().top } : null;
  if (fn) fn(el.dataset, el, e);
}
// Touch taps run on finger-up: iOS sometimes spends the first tap on a
// "hover" and only clicks on the second. A tap that moved (a scroll) or
// was taken over by the browser doesn't count; the click iOS sends after
// a handled tap is skipped.
let tapStart = null, tapDone = null;
$app.addEventListener('pointerdown', e => {
  if (e.pointerType === 'mouse') { tapStart = null; return; }
  const el = e.target.closest('[data-act]');
  tapStart = el ? { el, x: e.clientX, y: e.clientY, t: Date.now() } : null;
});
$app.addEventListener('pointercancel', () => { tapStart = null; });
$app.addEventListener('pointerup', e => {
  const s = tapStart;
  tapStart = null;
  if (!s || e.pointerType === 'mouse') return;
  const el = e.target.closest('[data-act]');
  if (el !== s.el || el.disabled || Math.hypot(e.clientX - s.x, e.clientY - s.y) > 10 || Date.now() - s.t > 800) return;
  tapDone = { el, t: Date.now() };
  runAct(el, e);
});
$app.addEventListener('click', e => {
  const el = e.target.closest('[data-act]');
  if (!el) return;
  if (tapDone && Date.now() - tapDone.t < 800) { tapDone = null; return; }
  runAct(el, e);
});
// No zooming of any kind (pinch included).
for (const ev of ['gesturestart', 'gesturechange']) document.addEventListener(ev, e => e.preventDefault(), { passive: false });

$app.addEventListener('change', e => {
  if (e.target.id === 'fileInput' && e.target.files[0]) loadFile(e.target.files[0]);
  if (e.target.id === 'origInput' && e.target.files[0]) loadReference(e.target.files[0]);
});

// ---------------------------------------------------------------------------
// Loading / exporting

// The league pack that belongs to this save, if one is kept here and most of
// its players are in the save.
function matchingPack(L) {
  const pack = readPack(L.shortName || L.leagueName || 'league');
  return pack && packMatch(pack, L) >= 0.8 ? pack : null;
}
// Picks and fan bases a franchise lost on the way through the game, offered once per save.
async function packPrompt(pack) {
  for (let i = 0; i < 60 && document.querySelector('.overlay'); i++) await new Promise(r => setTimeout(r, 500));   // after the rules question
  const L = league();
  const key = `hlc:packdone:${pack.league}:${saveTag(L)}:${L.season.currentYear}`;
  try { if (localStorage.getItem(key)) return; } catch {}
  const picks = packPickDiffs(pack, L), teams = packTeamDiffs(pack, L);
  if (!picks.length && !teams.length) return;
  const lines = [...picks.slice(0, 6).map(d => `${d.yr} R${d.rd} (${L.teams.find(t => t.id === d.otid)?.shortName}) back to ${L.teams.find(t => t.id === d.tid)?.shortName}`), ...(picks.length > 6 ? [`and ${picks.length - 6} more picks`] : []), ...(teams.length ? [`${teams.length} teams' fans or tags`] : [])];
  const r = await choiceBox(`<b>${esc(pack.name)}</b> had some things the game dropped:<br><span class="small muted">${lines.map(esc).join('<br>')}</span>`, [['no', 'Leave As Is', 'off'], ['yes', 'Apply My League', 'focus']]);
  try { localStorage.setItem(key, '1'); } catch {}
  if (r !== 'yes') return;
  const n = applyPackPicks(picks, L) + applyPackTeams(teams);
  state.dirty = true; render();
  toast(`Applied ${n} changes`, 'Export the season file to keep them.');
}

// A traits file (the backup): into the open save if it's that league's, otherwise kept for that save's next load.
async function loadTraitsFile(data) {
  const L0 = state.data?.seasonLeagues[0];
  if (L0 && !isCollege() && sameSave(data)) {
    if (!(await confirmBox(`Load the traits from <b>${esc(data.save || 'this file')}</b> (saved ${esc(new Date(data.at).toLocaleString())}) into this save? They replace the traits here.`, 'Load Traits'))) return;
    applyTraitsBackup(data);
    render();
    toast('Traits loaded', `${Object.keys(data.traits).length} players.`);
  } else {
    // No matching save open: keep it for that save, used when it loads.
    const id = `${data.league}:${data.save}#${data.team}`;
    try { localStorage.setItem(`hlc:traits:${id}`, JSON.stringify({ v: 2, at: data.at, m: data.traits })); for (const [yr, v] of Object.entries(data.drift || {})) localStorage.setItem(`hlc:drift:${id}:${yr}`, JSON.stringify(v)); } catch { /* ignore */ }
    toast('Traits file kept', `They load with that save (${data.save}, team ${data.team}).`);
  }
}
async function loadFile(file) {
  // A traits file doesn't replace the save: no unsaved-changes question for it.
  if (file.size < 3e6) { try { const d = JSON.parse(await file.text()); if (isTraitsBackup(d)) return loadTraitsFile(d); } catch { /* not JSON: a save */ } }
  if (state.dirty && !(await confirmBox('You have unsaved changes. Load a different file anyway?', 'Load'))) return;
  const o = overlay('<div class="spinner"></div><p class="note">Reading season file…</p>');
  await nextFrame();
  try {
    const text = await file.text();
    let data = parseSave(text);
    if (isPack(data)) {
      savePack(data);
      o.remove();
      toast(`League pack kept: ${data.name}`, `${Object.keys(data.traits).length} players' traits, ${data.picks.length} pick holdings. Load a franchise from that league and it will offer them.`);
      return;
    }
    // A league file is the league object itself (no seasonLeagues wrapper): open it in the editor.
    state.leagueFile = false;
    if (!data.seasonLeagues && Array.isArray(data.teams) && data.season) { data = { seasonLeagues: [data] }; state.leagueFile = true; }
    if (!Array.isArray(data.seasonLeagues) || !data.seasonLeagues.length) throw new Error('No seasonLeagues found');
    state.fileName = file.name;
    state.undo = null;
    state.cal = {}; state.cutSel = {}; state.cutSeeded = false; state.rm = null; state.calLast = undefined;
    preloadLogos(data); state.logoWaited = false;   // start the team logos downloading before the heavy setup
    installData(data);
    if (state.leagueFile) {
      leagueTraitsIn(data.seasonLeagues[0]);
      state.depth = 'complete'; state.dirty = false;
      o.remove();
      toast(`Loaded league file: ${data.seasonLeagues[0].meta?.saveName || file.name}`, 'Edit it, then export it as a league file.');
      goHome();
      return;
    }
    if (!isCollege()) state.fileCheck = fileCheck(league());   // before the app touches anything
    if (!isCollege()) { state.probeCheck = probeCheck(league()); state.probeIn = { [state.leagueIdx]: probe(league()) }; }
    ledgerStart();
    freshSaveCheck();
    if (repairPickYears()) toast('Draft picks moved back a year', 'This save had its picks a year ahead; they now carry the real draft year.');
    recallSetup();
    unstampDraftYear();
    if (!isCollege() && undoMindNudges()) state.dirty = true;
    const reopened = reopenOptions();
    const reext = reopenExtensions();
    settlePromises();
    settleIncentives();
    advanceLoads();
    state.dirty = reopened > 0 || reext > 0;
    const held = holdCpuOffers();
    recordSalaries();
    if (isCollege()) { try { state.cal = JSON.parse(localStorage.getItem(collegeCalKey())) || {}; } catch { state.cal = {}; } }
    const kicked = applyExtensions();
    if (!isCollege() && lotteryDone(league())) settleProt(league());
    const filled = fillTraits(data.seasonLeagues[0]) + (state.leagueIdx ? fillTraits(data.seasonLeagues[state.leagueIdx]) : 0);
    if (!isCollege()) seedEgo(data.seasonLeagues[0]);
    if (filled) state.dirty = true;
    const pack = !isCollege() ? matchingPack(data.seasonLeagues[0]) : null;
    if (pack) { const n = applyPackTraits(pack, data.seasonLeagues[0]); if (n) toast(`Your traits restored for ${n} players`, pack.name); setTimeout(() => packPrompt(pack), 700); }
    // This save's own traits as you left them (edits, Ego, changes from events): the game doesn't keep them.
    if (!isCollege()) { loadTraitStore(data.seasonLeagues[0]); setTimeout(pullTraits, 0); }
    if (!state.leagueFile) { const n = cleanCoachPool(data.seasonLeagues[0]); if (n) state.coachPoolFixed = n; }
    const signedIn = isCollege() ? applyRecruiting() : 0;
    const planned = !isCollege() && applyClassPlan();
    if (!isCollege()) logClass(league());
    if (planned) setTimeout(() => toast('📅 Your planned class is in', `${league().draftClass.length} prospects. The game\'s own class can be put back in the Draft Class Lab.`), 1200);
    o.remove();
    if (!ALWAYS_COMPLETE && !isCollege() && !state.depth) setTimeout(depthPrompt, 400);
    toast(`Loaded ${data.seasonLeagues[0].meta?.saveName || file.name}`, [held ? `${held} CPU contract offers held until the options deadline.` : '', kicked ? `${kicked} extension${kicked > 1 ? 's' : ''} signed last summer kicked in.` : '', filled ? `Traits set for ${filled} players.` : '', signedIn ? `${signedIn} recruiting signings written in.` : ''].filter(Boolean).join(' '));
    render();
  } catch (err) {
    o.remove();
    console.error(err);
    const b = overlay(`<p class="note">Couldn't read that file as a Hoop Land season.<br><span class="muted small">${esc(err.message)}</span></p><button class="btn">OK</button>`);
    b.querySelector('button').onclick = () => b.remove();
  }
}

// Put parsed season data in place. `keepSnaps` keeps the original
// baselines (used when undoing an in-app phase advance).
function installData(data, keepSnaps = false) {
  {
    state.data = data;
    // The lottery format follows the file's year unless picked on the lottery screen.
    state.params.lotteryFormat = 'auto';
    // College franchise saves open on the college league.
    state.mode = detectMode(data);
    setGameClock(data.seasonLeagues);   // short games: minutes read on a 48-minute scale
    state.leagueIdx = state.mode.li;
    if (!keepSnaps) state.snaps.clear();
    state.profiles = [];
    state.leagueAvg = [];
    state.auto = {};
    state.rookieAuto = {};
    state.summer = {};
    state.summerTour = {};
    state.rookieNums = {};
    state.numPick = null;
    state.mentor = {};
    state.contracts = {};
    state.jerseys = {};
    state.fa = {};
    state.awards = {};
    state.draft = {};
    state.compPools = {};
    setStyleRefs(data.seasonLeagues[0]);
    state.compCache = {};
    data.seasonLeagues.forEach((L, li) => {
      const players = leaguePlayers(L, true).map(e => e.p);
      for (const p of players) if (!keepSnaps || !state.snaps.has(snapKey(p.id, li))) state.snaps.set(snapKey(p.id, li), snapshot(p));
      state.profiles[li] = buildSkillProfiles(players);
      const avg = ATTRS.map(() => 0);
      for (const p of players) ATTRS.forEach((k, i) => { avg[i] += p.attributes[k][0] / players.length; });
      state.leagueAvg[li] = avg;
    });
    data.seasonLeagues.forEach(L => { if (L.draftClass?.length) saveOriginals(L, originalRatings(L)); });
    preloadLogos(data); state.logoWaited = false;
    loadUserTeams();
  }
}

// Read a pre-draft save only to remember the prospects' original ratings.
async function loadReference(file) {
  const o = overlay('<div class="spinner"></div><p class="note">Reading pre-draft ratings…</p>');
  await nextFrame();
  try {
    const ref = parseSave(await file.text());
    const L = ref.seasonLeagues.find(x => x.shortName === league().shortName) || ref.seasonLeagues[0];
    if (!L.draftClass?.length) throw new Error('That file has no draft class. Use a save from before the draft.');
    const rookies = new Set(leagueRookies(league()).map(r => r.p.id));
    const found = Object.keys(originalRatings(L)).filter(id => rookies.has(+id)).length;
    if (!found) throw new Error("None of that file's prospects match this season's rookies.");
    saveOriginals(league(), originalRatings(L));
    state.compCache = {};
    o.remove();
    toast(`Pre-draft ratings found for ${found} rookies`);
    render();
  } catch (err) {
    o.remove();
    const b = overlay(`<p class="note">${esc(err.message)}</p><button class="btn">OK</button>`);
    b.querySelector('button').onclick = () => b.remove();
  }
}

// The new season starts with no held upgrade points: everyone's go into
// their ratings (the same weighting the CPU uses).
function spendAllPoints(L) {
  const rng = mulberry32((saveSalt() ^ 0xa9) >>> 0);
  let n = 0;
  for (const p of [...L.teams.flatMap(t => t.roster), ...(L.freeAgents || [])]) n += spendHeldPoints(p, state.params, rng);
  return n;
}
// Playbooks on for every pro team: the game reads "play selection" from a team's scoring option entries, and 1 means
// the team runs its playbook. The app has no scoring options of its own, so on export each team keeps up to three
// valid entries (a team with none gets three on Auto) and every entry is set to selection 1, whoever is first, second or third.
function usePlaybooks(L) {
  if (!L || L.leagueType !== 0) return;
  for (const t of L.teams) {
    const ids = new Set(t.roster.map(p => p.id));
    const keep = [];
    for (const o of t.scoringOptions || []) if (ids.has(o.pid) && !keep.some(k => k.pid === o.pid) && keep.length < 3) keep.push(o);
    const pool = [...t.roster].filter(p => p.status !== 4 && !keep.some(k => k.pid === p.id)).sort((a, b) => shownLevel(b) - shownLevel(a));
    // A team with no valid entry gets three on Auto; otherwise its own (or the CPU's) picks stand.
    if (!keep.length) while (keep.length < Math.min(3, t.roster.length) && pool.length) keep.push({ pid: pool.shift().id, usageRate: 0, focus: 0, playSelection: 1 });
    for (const o of keep) o.playSelection = 1;
    t.scoringOptions = keep;
  }
}
// The game releases players when a team is over its cap as the season starts (OKC went to 6). Before a free agency
// save goes out, every CPU team is brought under the game's cap with at least 13 players: overpaid veterans are dumped on
// teams with room (for nothing back, if that's what it takes), then the worst value is waived, then the roster is filled
// with minimum deals. Your teams aren't touched; the Export screen warns you instead.
const filePay = t => t.roster.reduce((a, p) => a + (p.contract?.sal || 0), 0);
// Salary relief the way a capped-out front office does it: overpaid veterans are moved to teams with room, for
// nothing back if that's the price. The core (three best players) and cheap young talent stay. Returns the log.
const cheapYoung = p => p.age <= 25 && (p.contract?.sal || 0) <= 12;
function dumpSalary(L, t, limit, pay = filePay, log = [], o = {}) {
  const sal = p => p.contract?.sal || 0;
  const overpaid = p => sal(p) - fairSalary(shownLevel(p));
  const core = new Set([...t.roster].sort((a, b) => shownLevel(b) - shownLevel(a)).slice(0, 3).map(p => p.id));
  // Rebuilding teams with room take the contracts first (that's what their space is for), then whoever has the most room.
  const others = L.teams.filter(x => x !== t && !isUserTeam(x));
  const reb = x => teamStatus(L, x) === 'rebuilding' ? 0 : 1;
  // A full team makes room by releasing a one-year minimum (a camp deal: nothing owed).
  const camp = x => FA.signedRoster(x).filter(q => (q.contract?.yrs || 0) <= 1 && sal(q) <= lateMin(q) + 1 && !core.has(q.id)).sort((a, b) => fillScore(a) - fillScore(b))[0];
  const spot = x => FA.signedRoster(x).length < FA.FA_DEFAULTS.seasonMax || !!camp(x);
  const fits = (x, p) => o.picks ? FA.capSpace(L, x) >= sal(p) && (FA.signedRoster(x).length < FA.FA_DEFAULTS.cpuRosterMax || spot(x)) : limit - pay(x) >= sal(p) + 4 && spot(x);
  for (let guard = 0; pay(t) > limit && guard < 10; guard++) {
    const over = pay(t) - limit;
    const cands = FA.signedRoster(t).filter(p => !core.has(p.id) && !cheapYoung(p) && sal(p) > 0 && !tradeLock(p) && !FA.isLifer(L, p, t) && (!o.onlyOverpaid || overpaid(p) >= 3)).sort((a, b) => overpaid(b) - overpaid(a) || sal(b) - sal(a));
    const order = [...cands.filter(p => sal(p) >= over && overpaid(p) > -3), ...cands];
    let moved = false;
    for (const p of order) {
      const to = others.filter(x => fits(x, p) && cpuPhysical(p, x) !== 'fail').sort((a, b) => reb(a) - reb(b) || pay(a) - pay(b))[0];
      if (!to) continue;
      const picks = o.picks ? dumpPicks(L, t, Math.max(0, overpaid(p)) * Math.max(1, p.contract?.yrs || 1)) : [];
      if (cpuPhysical(p, to) === 'flag') { const sw = sweetener2nd(L, t, picks); if (sw) picks.push(sw); }
      executeTrade({ team: t, players: [p], picks, prospects: [] }, { team: to, players: [], picks: [], prospects: [] }, L.season.currentYear);
      if (reb(to) === 0 && p.age >= 28 && !FA.isLifer(L, p, to) && p.season && p.season.onTradeBlock !== 2) p.season.onTradeBlock = 1;
      const max = o.picks ? FA.FA_DEFAULTS.cpuRosterMax : FA.FA_DEFAULTS.seasonMax;
      if (FA.signedRoster(to).length > max) { const c = camp(to); if (c) { FA.cutPlayer(L, to, c); log.push(`${to.shortName} released ${playerName(c)} to make room`); } }
      log.push(`${t.shortName} dumped ${playerName(p)} ($${sal(p)}M) on ${to.shortName}${picks.length ? ` with ${picks.map(pk => `a ${pk.yr} ${pk.rd === 1 ? '1st' : '2nd'}`).join(' and ')}` : ''}`);
      moved = true;
      break;
    }
    if (!moved) break;
  }
  return log;
}
// The price of a salary dump in picks, by how much dead weight goes out (overpay × years): a 2nd for a modest one,
// a 1st for a big one, both for the worst. Own picks only, furthest out first, never a frozen, protected or lottery-locked one.
function dumpPicks(L, t, weight) {
  const own = rd => t.draftPicks.filter(pk => pk.rd === rd && pk.otid === t.id && pk.yr > draftYear(L) && !FA.pickFrozen(L, t, pk) && !isProt(pk) && !lotteryLocked(pk)).sort((a, b) => b.yr - a.yr)[0];
  const out = [];
  if (weight >= 25) { const f = own(1); if (f) out.push(f); }
  if (weight >= 6 && (weight >= 45 || !out.length)) { const s2 = own(2); if (s2) out.push(s2); }
  return out;
}
// Late in free agency the teams at the top of the cap (over the 1st apron, or over the tax and not contending) move
// their overpaid veterans to rebuilding teams with space, paying in picks, even for less back.
function apronDumps(L) {
  if (!FA.capSystemOn()) return [];
  const c = FA.capLines(L), log = [];
  for (const t of L.teams.filter(x => !isUserTeam(x))) {
    const pay = FA.teamCommitted(t);
    const limit = pay > c.apron1 ? c.apron1 : pay > c.tax && teamStatus(L, t) !== 'contending' ? c.tax : null;
    if (limit != null) dumpSalary(L, t, limit, FA.teamCommitted, log, { picks: true, onlyOverpaid: true });
  }
  if (log.length) (calFlags().dumpLog ||= []).push(...log);
  return log;
}
// Filling out a roster: the best minimum-deal players left, with a lean to youth, as long as the signing doesn't
// push the team into its next tax bracket (or, for the game's floor, past the 2nd apron).
const fillScore = p => shownLevel(p) + (p.age <= 23 ? 4 : p.age <= 25 ? 2 : 0) + Math.min(4, p.pot || 0);
function fillRoster(L, t, to, list, { floor = 0, skip = new Set() } = {}) {
  while (FA.signedRoster(t).length < to) {
    const need = FA.signedRoster(t).length < floor;
    const p = (L.freeAgents || []).filter(x => x.status === FA.STATUS_FREE && !skip.has(x.id)).sort((a, b) => fillScore(b) - fillScore(a))
      .find(x => !FA.capSystemOn() || (need ? FA.teamCommitted(t) + lateMin(x) <= FA.capLines(L).apron2 : lateMin(x) <= FA.bracketRoom(L, t)));
    if (!p) break;
    FA.signPlayer(L, p, t, { tid: t.id, sal: lateMin(p), yrs: 1, opt: 0 }, L.season.currentDay || 3);
    lockSigning(p, 'Signed this offseason');
    list?.push({ p, t });
  }
}
// A rebuilding team shops its veterans who could help a contender (28 and up, rotation level or better), the contracts
// it took on included, so they're on the game's trading block when the season starts. Untouchables stay put.
function rebuildBlock(L) {
  for (const t of L.teams.filter(x => !isUserTeam(x) && teamStatus(L, x) === 'rebuilding'))
    for (const p of FA.signedRoster(t)) if (p.season && p.season.onTradeBlock === 0 && p.age >= 28 && shownLevel(p) >= 70 && !tradeLock(p) && !FA.isLifer(L, p, t)) p.season.onTradeBlock = 1;
  // A franchise lifer is never shopped: he finishes his career where he is.
  for (const t of L.teams.filter(x => !isUserTeam(x))) for (const p of FA.signedRoster(t)) if (p.season?.onTradeBlock === 1 && FA.isLifer(L, p, t)) p.season.onTradeBlock = 0;
}
function gameCapCheck(L, cap) {
  if (!cap) return [];
  const log = [], yr = L.season.currentYear, MIN_ROSTER = 13, waived = new Set();
  const sal = p => p.contract?.sal || 0;
  const overpaid = p => sal(p) - fairSalary(shownLevel(p));
  const room = t => cap - filePay(t);
  for (const t of L.teams.filter(x => !isUserTeam(x))) {
    // Under the cap with room left for the minimum deals a short roster still needs.
    const roomFor = () => Math.max(0, MIN_ROSTER - FA.signedRoster(t).length) * 3;
    dumpSalary(L, t, cap - roomFor(), filePay, log);
    // Nobody could take enough: waive the worst value for the money (it stays on the app's books as dead money).
    const core = new Set([...t.roster].sort((a, b) => shownLevel(b) - shownLevel(a)).slice(0, 3).map(p => p.id));
    for (let guard = 0; room(t) < roomFor() && guard < 10; guard++) {
      const p = FA.signedRoster(t).filter(x => !core.has(x.id) && sal(x) > 0 && !FA.isLifer(L, x, t)).sort((a, b) => (cheapYoung(a) - cheapYoung(b)) || overpaid(b) - overpaid(a) || sal(b) - sal(a))[0];
      if (!p) break;
      const c = { ...p.contract };
      FA.cutPlayer(L, t, p);
      waived.add(p.id);
      if (c.yrs > 1) { const led = deadLedger(); led.push({ pid: p.id, name: playerName(p), tid: t.id, sal: c.sal, yrs: c.yrs - 1, yr: yr + 1 }); saveDead(led); }
      log.push(`${t.shortName} waived ${playerName(p)} ($${c.sal}M)`);
    }
    while (FA.signedRoster(t).length < MIN_ROSTER) {
      const p = (L.freeAgents || []).filter(x => x.status === FA.STATUS_FREE && !waived.has(x.id) && lateMin(x) <= room(t)).sort((a, b) => fillScore(b) - fillScore(a))[0];
      if (!p) break;
      FA.signPlayer(L, p, t, { tid: t.id, sal: lateMin(p), yrs: 1, opt: 0 }, L.season.currentDay || 3);
      log.push(`${t.shortName} filled with ${playerName(p)} ($${lateMin(p)}M)`);
    }
    // Then up to 15 on one-year minimums, as long as nobody pushes the team into its next tax bracket or past the game's cap.
    const adds = [];
    fillRoster(L, t, FA.FA_DEFAULTS.seasonMax, adds, { skip: waived });
    for (const { p } of adds) if (filePay(t) > cap) { FA.cutPlayer(L, t, p); waived.add(p.id); } else log.push(`${t.shortName} filled with ${playerName(p)} ($${lateMin(p)}M)`);
  }
  if (log.length) { calFlags().capCheckLog = log; state.dirty = true; }
  return log;
}
// A summer file exported before Roster Finalization still carries summer rosters (up to 18). The game trims anyone
// over 15 when the season starts by its own rule, which doesn't look at how good a player is (it let Lv 87 players go
// and kept Lv 62 rookies). So the CPU teams make their cuts here first, the same way they do at Roster Finalization.
const overFifteen = L => L.teams.filter(t => FA.signedRoster(t).length > FA.FA_DEFAULTS.seasonMax);
function exportCuts(L) {
  if (isCollege() || L.season.phase !== BUMP_PHASES[0] || calFlags().cuts) return [];
  const log = [];
  for (const t of overFifteen(L).filter(x => !isUserTeam(x))) {
    const n = FA.signedRoster(t).length - FA.FA_DEFAULTS.seasonMax;
    for (const { p } of cutRank(t).filter(x => !FA.isLifer(L, x.p, t)).slice(0, n)) { FA.cutPlayer(L, t, p); log.push(`${t.shortName} cut ${playerName(p)}`); }
    // Not enough expiring deals to cut: the lowest-value of the rest (never the eight best).
    const left = FA.signedRoster(t).length - FA.FA_DEFAULTS.seasonMax;
    if (left > 0) {
      const top = new Set([...FA.signedRoster(t)].sort((a, b) => shownLevel(b) - shownLevel(a)).slice(0, 8).map(p => p.id));
      const rest = FA.signedRoster(t).filter(p => !top.has(p.id) && !FA.isLifer(L, p, t)).sort((a, b) => FA.cutScore(a, shownLevel(a), L.season.currentYear) - FA.cutScore(b, shownLevel(b), L.season.currentYear));
      for (const p of rest.slice(0, left)) { FA.cutPlayer(L, t, p); log.push(`${t.shortName} cut ${playerName(p)}`); }
    }
  }
  if (log.length) { calFlags().exportCuts = log; state.dirty = true; }
  return log;
}
let restoreCap = null;
function buildExport() {
  restoreCap = null;
  if (state.leagueFile) return buildLeagueExport();
  state.data.seasonLeagues.forEach((L, li) => { if (state.summer[li]) markSummerDone(L); });
  if (!isCollege() && league().season.phase === BUMP_PHASES[0]) spendAllPoints(league());
  // The game's cap becomes this season's 2nd apron (room for in-season
  // moves), with the max contract tiers scaled so a max is still 25 / 30 /
  // 35% of the real cap.
  if (!isCollege()) {
    const L = league(), cs = leagueCapSettings(L);
    if (cs) {
      // Simple rules read the save's own cap in the app, so it's put back after the file is built.
      if (!FA.capSystemOn()) restoreCap = [L.season.salaryCap, L.season.maxContract];
      L.season.salaryCap = cs.cap; L.season.maxContract = cs.maxContract;
    }
  }
  // College: once Signing Day is written in, the file goes out on the last
  // day of the signing period (like pro free agency), so one more advance
  // in the game starts the new season.
  if (isCollege() && market()?.applied) {
    const s = league().season;
    if (s.phase === 6) s.currentDay = s.signingDays || 3;
  }
  if (!isCollege() && league().season.phase === 6) { exportCuts(league()); gameCapCheck(league(), league().season.salaryCap); rebuildBlock(league()); }
  if (!isCollege()) pickWindow(league());
  rememberExport();
  // The game extends a pile of players when the season opens, at values we
  // don't want. A file leaving free agency goes out with everyone's extension
  // eligibility off; the next offseason reopens it (reopenExtensions).
  const shut = shutExtensions();
  clearSeasonPoints();
  const stamped = stampDraftYear();
  // History starts: the starting year (the game scrolls back as far as it), on every league in the save.
  const startWas = (!isCollege() && state.params.startYear > 0) ? state.data.seasonLeagues.map(x => x.season.startingYear) : null;
  if (startWas) state.data.seasonLeagues.forEach(x => { x.season.startingYear = state.params.startYear; });
  state.data.seasonLeagues.forEach(usePlaybooks);
  // Extensions go out in the contract's extension slot (the salary stays the current deal's): the game kicks them in
  // when the season ends. The app's ledger is a fallback for a deal that comes back expiring without one.
  if (!isCollege()) { writeLedger(); saveManifest(league()); saveProbe(league()); saveTraitStore(); pushTraits(); cleanCoachPool(league()); }   // free-agent coaches go out clean, so the game lists them
  const nudged = !isCollege() ? applyMindNudges(league()) : [];
  const text = serializeSave(state.data);
  for (const [p, k, d] of nudged) p.tendencies[k] -= d;
  state.lastNudge = nudged.length;
  if (startWas) state.data.seasonLeagues.forEach((x, i) => { x.season.startingYear = startWas[i]; });
  if (restoreCap) { [league().season.salaryCap, league().season.maxContract] = restoreCap; restoreCap = null; }
  for (const p of shut) p.contract.canExt = true;
  for (const p of stamped) p.history.draft.yr++;
  return new File([text], state.fileName, { type: 'application/octet-stream' });
}

// Running as a claude.ai artifact: files are saved through the viewer's
// download prompt, which needs an allowed extension (.json).
const inArtifact = () => typeof window.claude?.use === 'function';
const artifactName = name => (/\.[a-z0-9]{2,4}$/i.test(name) ? name : `${name}.json`);

async function artifactSave(name, data) {
  const dl = await window.claude.use('downloads');
  if (!dl) { toast('Saving isn\'t available in this view'); return false; }
  try {
    await dl.save({ filename: artifactName(name), data });
    return true;
  } catch (err) {
    if (err?.code !== 'declined') toast(`Save failed: ${err?.message || err?.code || 'unknown error'}`);
    return false;
  }
}

actions.download = async () => {
  const o = overlay('<div class="spinner"></div><p class="note">Building file…</p>');
  await nextFrame();
  const file = buildExport();
  if (inArtifact()) {
    o.remove();
    if (await artifactSave(file.name, file)) { state.dirty = false; toast('Season file saved. Remove .json from the name before loading it in Hoop Land.'); }
    return;
  }
  const url = URL.createObjectURL(file);
  const a = document.createElement('a');
  a.href = url;
  a.download = file.name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10000);
  o.remove();
  state.dirty = false;
  toast('Season file saved');
};

// The game's cap setting in a league file is this season's 2nd apron (the
// highest line, room for in-season moves); the max contract tiers are scaled
// so a max is still 25 / 30 / 35% of the real cap. Same as the season file.
function leagueCapSettings(L) {
  if (isCollege()) return null;
  const C = FA.capLinesFor(FA.seasonStart(L)), real = FA.capSystemOn() ? FA.capLines(L) : C;
  if (FA.capSystemOn()) return { cap: real.apron2, maxContract: [25, 30, 35].map(t => Math.round(t * real.cap / real.apron2)) };
  // Simple rules: max contracts of $50M / $40M / $30M (a 25-20-15 split, $50M on top). The file stores whole percents of
  // the cap, so they only come out exact on a $200M or $250M cap: an apron line that is one of those is used as is,
  // otherwise the first of them at or above the 1st apron (still past the first number, so nothing is cut short).
  const want = [30, 40, 50];
  const exact = cap => want.every(d => (d * 100) % cap === 0);
  const line = [C.apron1, C.apron2].find(exact) ?? [200, 250, 500].find(c => c >= C.apron1);
  return { cap: line, maxContract: want.map(d => Math.round(d * 100 / line)) };
}

// A franchise save back into a league file, to start new saves from it.
actions.downloadLeague = async () => {
  const L = league();
  // Unsettled contracts: the game decides them itself when a new league loads
  // (who re-signs, and for how much), so finish free agency here first if you
  // want your own deals in the file.
  const open = L.teams.flatMap(t => t.roster).filter(p => p.status === FA.STATUS_EXPIRING).length;
  let settle = false;
  if (open) {
    const pick = await choiceBox(`<b>${open} players</b> still have expiring contracts. The game will re-sign or release them on its own when the league loads, and builds its own extensions. Finish free agency here first to keep your own deals, or let the app estimate who re-signs.`, [['no', 'Cancel', 'off'], ['go', 'Leave to the game', ''], ['settle', 'Estimate re-signings', 'focus']]);
    if (pick !== 'go' && pick !== 'settle') return;
    settle = pick === 'settle';
  }
  const o = overlay('<div class="spinner"></div><p class="note">Building league file…</p>');
  await nextFrame();
  if (L.season.phase === BUMP_PHASES[0]) spendAllPoints(L);
  const C = saveToLeague(L, { keepDraft: L.season.phase < 5, settle, ...(leagueCapSettings(L) || {}) });
  usePlaybooks(C);
  cleanCoachPool(C);
  if (!isCollege() && state.params.startYear > 0) C.season.startingYear = state.params.startYear;
  const name = `${state.fileName.replace(/\.[a-z0-9]{2,4}$/i, '')} LEAGUE`;
  const file = new File([serializeSave(C)], name, { type: 'application/octet-stream' });
  // The pack: traits, far-out traded picks, fans and tags, for giving back to a franchise started from this league.
  const pack = buildPack(C, name);
  savePack(pack);
  const packFile = new File([JSON.stringify(pack)], `${name} PACK.json`, { type: 'application/json' });
  o.remove();
  const give = async f => {
    if (inArtifact()) return artifactSave(f.name, f);
    const url = URL.createObjectURL(f);
    const a = document.createElement('a');
    a.href = url; a.download = f.name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 10000);
    return true;
  };
  const ok = await give(file);
  if (ok) await give(packFile);
  if (ok) toast('League file and pack saved', inArtifact() ? 'Remove .json from the league file name. Load the pack file on any device to give a franchise its traits back.' : 'Start a franchise from the league file. The pack gives it your traits, picks and fans back.');
};

actions.share = async () => {
  const o = overlay('<div class="spinner"></div><p class="note">Building file…</p>');
  await nextFrame();
  const file = buildExport();
  o.remove();
  try {
    await navigator.share({ files: [file], title: file.name });
    state.dirty = false;
  } catch (err) {
    if (err.name !== 'AbortError') toast('Sharing failed, use Download instead');
  }
};

// ---------------------------------------------------------------------------
// Offseason timeline: advance the save phase by phase inside the app

// Keep the file as it was before an advance, so it can be undone once.
// Checkpoints before big moves: the last three are kept (each is a full copy of the save, so no more than that on a
// phone), and Settings → Data can go back to any of them.
function checkpoint(label) {
  state.undo = { label, text: serializeSave(state.data), dirty: state.dirty, at: Date.now(), cal: JSON.stringify(state.cal || {}), ledgerN: ledgerLen() };
  state.undoList = [state.undo, ...(state.undoList || [])].slice(0, 3);
}
function undoHistoryBox() {
  const list = state.undoList || [];
  const ago = t => { const m = Math.round((Date.now() - t) / 60000); return m < 1 ? 'just now' : m < 60 ? `${m} min ago` : `${Math.round(m / 60)} h ago`; };
  return setGroup('Undo History', [list.length ? list.map((u, i) => `<div class="set-row"><span class="grow small">${esc(u.label)} <span class="muted">· ${ago(u.at)}</span></span><button class="btn small" data-act="undoTo" data-i="${i}">↺ Back to before this</button></div>`).join('')
    : '<p class="note small muted">Nothing to undo yet. Big moves (the lottery, the draft, free agency days, cuts) save a checkpoint first.</p>', '<span class="note muted small">The last three checkpoints this session. Going back drops anything done after it.</span>']);
}
actions.undoTo = async d => {
  const u = (state.undoList || [])[+d.i];
  if (!u || !(await confirmBox(`Go back to before <b>${esc(u.label)}</b>? Everything done since is dropped.`, 'Go Back'))) return;
  const o = overlay('<div class="spinner"></div><p class="note">Restoring…</p>');
  await nextFrame();
  installData(parseSave(u.text), true);
  ledgerRewind(u.ledgerN);   // coins and fans go back with the save
  try { state.cal = JSON.parse(u.cal || '{}'); } catch { /* keep */ }
  if (!isCollege()) { saveDrift(); saveTraitStore(); saveComeback(); saveJersey(); }
  state.undoList = state.undoList.slice(+d.i + 1);
  state.undo = state.undoList[0] || null;
  state.dirty = u.dirty;
  o.remove();
  goHome();
  toast(`Back to before ${u.label}`);
};

// ---------------------------------------------------------------------------
// Offseason calendar: one step at a time, June to October

// Where the save is in the offseason (0 = season over, before Pre-Lottery).
function phaseRank(s) {
  if (s.phase === 6) return 3 + Math.max(1, Math.min(3, s.currentDay || 1));
  return { 2: 1, 4: 2, 5: 3 }[s.phase] ?? 0;
}
const calFlags = () => (state.cal ||= {});
const faDone = day => {
  const s = league().season;
  if (phaseRank(s) > 3 + day) return true;
  const fa = state.fa[state.leagueIdx];
  return s.phase === 6 && s.currentDay === day && ((fa?.day === day && fa.stage === 'done') || !!calFlags().faLog?.[day]);
};

// Each step: when, what, whether it's finished, and what it opens.
