  if (key === 'practice') { const t = league().teams.find(isUserTeam); if (!t) return 'Done.'; const r = practicePlan(t, shownLevel, p => tr(p, 'lockerRoom')); return `Captains: ${r.captains.map(x => playerName(x.p)).join(' and ') || 'none named'}.`; }
