  useStyle(t, c, preset, pr.focusId, !!fxNow().hybrid);
  S.log.push({ yr: pr.yr, tid: t.id, kind: 'shift', coach: pr.coach, from: pr.from, to: pr.style, focus: pr.focus, why: pr.reasons });
  delete S.props[t.id];
